import json
p='country_unique.json'
d=json.load(open(p,encoding='utf8'))
L=["https://www.lot.com/pl/en/help-center/baggage/how-much-cash-can-you-travel-with-by-plane1","LOT Polish Airlines: How much cash can you travel with?"]
d['cash']['poland']={"h":"What LOT Polish Airlines says about cash on flights from Poland","p":["LOT's help page says that between Schengen countries you do not need to declare cash, even above 10,000 euros. If your trip crosses the Schengen border, amounts of 10,000 euros or more must be declared to the customs authority.","For flights to or from the USA, LOT gives US$10,000 as the limit for funds you can carry without declaring. It lists what counts as declarable: banknotes and coins in Polish or foreign currency, withdrawn coins of value, securities, cheques, bills of exchange and precious metals such as gold or silver coins and bars.","LOT adds that these limits apply to every way of crossing a border, not only flying, and points to official government sites for current limits. The airline page is not the customs authority's, so confirm with Polish customs."],"src":"Unofficial source, read 22 November 2026: LOT Polish Airlines help page \"How much cash can you travel with?\". It is an airline page, not the customs authority's.","link":L}
open(p,'w',encoding='utf8',newline='').write(json.dumps(d,separators=(',',':'),ensure_ascii=False))
